# GENERATED by prepare_system_vectors.py; predecessor monitors/failures preserved.
# GENERATED by make_system_cpu.py; initial failing integration preserved.
"""CPU + native MMIO/keyboard/raster regression, distinct from power signoff."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import subprocess
import tempfile
import run_video_cpu_async as predecessor
from run_rtl import BASE, fixtures, program_fixture, run
from run_execution_netlist import prepare_guard
from make_stack_cpu import transform_bench as stack_fixture

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'verification/net19a'
MODELS = ['sim/hdl/hc_models.sv', 'sim/net02/package_models.sv', 'sim/net03/package_models.sv',
          'sim/net04/package_models.sv', 'hardware/cpu_global/cpu_global_netlist.sv',
          'hardware/memory_decode/memory_decode_netlist.sv', 'sim/net19a/package_models.sv','hardware/system_access/system_access_netlist.sv',
          'sim/net13/memory_devices.sv', 'hardware/memory_bus/memory_bus_netlist.sv',
          'sim/net14c/package_models_async.sv', 'sim/net14c/video_raster_async_netlist.sv',
          'hardware/keyboard_500/keyboard_500_netlist.sv', 'sim/net19a/isa1_memory_system.sv']


def fixture(text, timed, refs):
    text = predecessor.fixture(text, timed, refs)
    # Existing vector benches seed architectural state, now at the actual FF
    # bits, not procedural peripheral output registers. Full program has none.
    seeds = {'boot': ('5', True), 'vb': ('1:0', False), 'eb': ('2', False), 'row': ('4:3', False)}
    for name, (bits, invert) in seeds.items():
        pattern = r'memory\.' + name + r'=([^;]+);'
        text = re.sub(pattern, lambda m: 'memory.peripheral.U1.q[' + bits + ']=' + ('~(' + m[1] + ')' if invert else m[1]) + ';', text)
    # Hardware column readiness can require 16,384 backend edges. A previous
    # 3,000 CPU-edge watchdog assumed instantaneous columns, now too short.
    text = text.replace('repeat(3000)begin', 'repeat(100000)begin')
    # Stage peripheral FFs off-edge BEFORE the epoch update. Preserve the
    # original atomic memory generation/array seeds, then seed CPU on a falling
    # edge. Program firmware never uses these vector-only state seeds.
    pattern=r'(?:memory\.peripheral\.U1\.q\[[^\]]+\]=[^;]+;\s*)+'
    matches=list(re.finditer(pattern,text))
    for match in reversed(matches):
        block=match[0]
        text=text[:match.start()]+text[match.end():]
        epoch=text.rfind('memory.generation=',0,match.start())
        if epoch<0:raise ValueError('Peripheral seed lacks preceding fixture epoch')
        stage='@(negedge memory.backend_clk);#0.01;\n     '+block+'\n     @(negedge clk);\n     '
        text=text[:epoch]+stage+text[epoch:]
    # HC174 captures NEXT at its own CLK edge; Q (and decoded BOOT) may
    # change after IO_COMMIT has fallen. Check the sampled permission, not
    # the later level. The original failing monitor is retained in development.
    old_monitor=' always @(boot or vb or eb or row)if(active && req && reset_n && power_good)\n   if(!memory.io_commit)$fatal(1,"MMIO change outside physical commit");\n'
    new_monitor=' reg sampled_mmio_write=0;\n always @(posedge memory.peripheral.U1.clk)\n   sampled_mmio_write=memory.io_commit && memory.saved_write && memory.select[3] && (|memory.io_select[3:0]);\n always @(memory.peripheral.U1.q)if(active && reset_n && power_good)\n   if(sampled_mmio_write!==1\'b1)$fatal(1,"MMIO register changed without sampled commit");\n'
    if old_monitor in text:
        if text.count(old_monitor)!=1:raise ValueError('Unexpected MMIO monitor multiplicity')
        text=text.replace(old_monitor,new_monitor)
    return text


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--timed', action='store_true')
    parser.add_argument('--early', action='store_true')
    parser.add_argument('--quick', action='store_true')
    parser.add_argument('--negative-bank',action='store_true')
    parser.add_argument('--legacy-state',action='store_true')
    parser.add_argument('--bench', choices=['cpu', 'program', 'guards', 'safety'], default='cpu')
    args = parser.parse_args()
    bench = {'cpu': 'tb_rtl_cpu', 'program': 'tb_rtl_program', 'guards': 'tb_stack_guards', 'safety': 'tb_rtl_safety'}[args.bench]
    OUT.mkdir(parents=True, exist_ok=True)
    refs = json.loads((ROOT / 'hardware/cpu_global/design.json').read_text())['reference_map']
    source_names = MODELS + ['tools/run_system_vectors.py','tools/prepare_system_vectors.py','tools/run_system_cpu.py','tools/make_system_cpu.py','tools/run_keyboard_cpu.py', 'tools/make_keyboard_cpu.py', 'tools/run_video_cpu_async.py',
                            'sim/tests/' + bench + '.sv', 'verification/net19a/adapter-origin.json',
                            'hardware/keyboard_500/design.json', 'hardware/keyboard_access/design.json','hardware/system_access/design.json','verification/net19a/native/system_access.xml','tools/build_system_access.py','references/ti/sn74ahc174.pdf',
                            'verification/net17/native/keyboard_500.xml', 'verification/net15/access/keyboard_access.xml',
                            'tools/run_rtl.py', 'firmware/rtl01_diagnostic.asm']
    # The controller XML's directory is defined by its preserved builder.
    source_names = [n for n in source_names if n != 'verification/net15/access/keyboard_access.xml'] + ['verification/net15/access/keyboard_access.xml']
    report = {'date': '2026-11-26', 'scope': 'CPU/raster/memory/native MMIO/keyboard with three AHC174 controller state packages and off-edge fixture bank seeds; global predecessor reset stimulus, binary reset boundary and ideal switch stimuli. No NET18 analog-power/global PCB/MTBF signoff',
              'bench': bench, 'negative_bank':args.negative_bank,'legacy_state':args.legacy_state,'early_state_cq': args.early, 'timed': args.timed, 'quick': args.quick,
              'iverilog': subprocess.run(['iverilog', '-V'], capture_output=True, text=True).stdout.splitlines()[0],
              'sources': [{'path': n, 'sha256': hashlib.sha256((ROOT / n).read_bytes()).hexdigest()} for n in source_names],
              'runs': [], 'failures': [], 'production_released': False}
    target = OUT / ('verified-' + args.bench + ('-negative-bank' if args.negative_bank else '-legacy-state' if args.legacy_state else '') + ('-early' if args.early else '') + ('-timed' if args.timed else '-ideal') + ('-quick' if args.quick else '') + '.json')
    with tempfile.TemporaryDirectory(prefix='isa1-keyboard-cpu-') as tmp:
        work = Path(tmp)
        for lane in range(4):
            data = (BASE / f'control_lane{lane}.bin').read_bytes()
            (work / f'control_lane{lane}.hex').write_text(''.join(f'{x:02x}\n' for x in data))
            report['sources'].append({'path': (BASE / f'control_lane{lane}.bin').relative_to(ROOT).as_posix(), 'sha256': hashlib.sha256(data).hexdigest()})
        rows, report['opcode_cases'] = fixtures(args.quick)
        (work / 'vectors.hex').write_text(''.join(''.join(f'{value:08x}\n' for value in row) for row in rows))
        report['program'], frame, png = program_fixture(work)
        original = (ROOT / 'sim/tests' / (bench + '.sv')).read_text()
        if bench == 'tb_stack_guards':
            original = prepare_guard(stack_fixture(original))
        text = fixture(original, args.timed, refs)
        if args.early:text=text.replace('isa1_memory #(.TIMED(1)', 'isa1_memory #(.TIMED(1),.CONTROL_EARLY(1)')
        if args.negative_bank:
            if args.bench!='cpu':raise ValueError('Bank negative applies to CPU vector fixture')
            text=text.replace('endmodule'," initial begin wait(active && reset_n && power_good);force memory.peripheral.n_NEXT_0=1'b1;end\nendmodule")
        if args.timed and not args.legacy_state:
            text=text.replace('$finish;', '$display("STATE_TIMING observed_setup_ns=%0.3f/%0.3f/%0.3f",memory.access_controller.U1.min_setup,memory.access_controller.U2.min_setup,memory.access_controller.U3.min_setup);$finish;')
        path = work / (bench + '.sv')
        (OUT / ('verified-' + bench + ('-negative-bank' if args.negative_bank else '-legacy-state' if args.legacy_state else '') + ('-early' if args.early else '') + ('-timed' if args.timed else '-ideal') + '.sv')).write_text(text)
        report['adapted_bench_sha256'] = hashlib.sha256(text.encode()).hexdigest()
        path.write_text(text)
        command = ['iverilog', '-g2012', '-Wall', '-s', bench]
        if args.bench == 'cpu':
            command += [f'-P{bench}.CASES={len(rows)}']
        if args.bench == 'program':
            command += [f'-P{bench}.RETIREMENTS={report["program"]["retirements"]}', f'-P{bench}.BUS_COUNT={report["program"]["transactions"]}']
        models=[ROOT/n for n in MODELS]
        if args.legacy_state:
            original=ROOT/'hardware/keyboard_access/keyboard_access_netlist.sv'
            legacy=original.read_text().replace('module keyboard_access_netlist #(parameter TIMED=0)','module system_access_netlist #(parameter TIMED=0,EARLY=0)')
            legacy_path=work/'legacy_state.sv';legacy_path.write_text(legacy)
            models=[legacy_path if n=='hardware/system_access/system_access_netlist.sv' else ROOT/n for n in MODELS]
            report['negative_model_origin']={'path':original.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(original.read_bytes()).hexdigest(),'transformation':'Rename module only, restore all three physical HC174 models from preserved NET15'}
        command += ['-o', str(work / 'bench.vvp'), *map(str,models), str(path)]
        row = {'compile': run(command, work)}
        if row['compile']['exit'] == 0:
            row['execution'] = run(['vvp', str(work / 'bench.vvp')], work, timeout=1200)
        row['passed'] = row['compile']['exit'] == 0 and row.get('execution', {}).get('exit') == 0 and 'RESULT ' in row.get('execution', {}).get('stdout', '') and 'failures=0' in row['execution']['stdout']
        if args.negative_bank or args.legacy_state:
            wanted='MMIO register changed without sampled commit' if args.negative_bank else 'DFF data setup violation'
            row['expected_rejection']=wanted
            row['passed']=row['compile']['exit']==0 and row.get('execution',{}).get('exit',0)!=0 and wanted in row.get('execution',{}).get('stdout','')
        if args.bench == 'program' and row['passed']:
            row['frame_matches_reference'] = (work / 'frame.ppm').read_bytes() == frame
            row['passed'] = row['passed'] and row['frame_matches_reference']
            if row['passed']:
                (OUT / 'frame-system-ideal.png').write_bytes(png)
        report['runs'].append(row)
        if not row['passed']:
            report['failures'].append(bench)
        target.write_text(json.dumps(report, indent=2) + '\n')
        print(json.dumps({'bench': bench, 'negative_bank':args.negative_bank,'legacy_state':args.legacy_state,'early_state_cq': args.early, 'timed': args.timed, 'quick': args.quick, 'passed': row['passed'],
                          'compile_exit': row['compile']['exit'], 'execution': row.get('execution'), 'compile_stderr': row['compile']['stderr']}), flush=True)
    return int(bool(report['failures']))


if __name__ == '__main__':
    raise SystemExit(main())
